export function tw(input) {
  if (typeof input === "function") return (...args) => tw(input(...args));
  if (typeof input !== "string") return input ?? "";
  const semantic = input.split(/\s+/).filter(Boolean);
  return input + " " + semantic.map((name) => adasaTailwind[name] || "").filter(Boolean).join(" ");
}
